/** English channel names resolve automatically; manual correction is optional. */
final class OnlineChannelLogo {
 static Bitmap fetch(Context context,String name,String id,String nativeId)throws Exception{
  Bitmap factory=FactoryProvider.logo(context,name,nativeId);if(factory!=null)return factory;SatelliteState state=SatelliteState.read(context);if(state.channelId.equals(nativeId)&&ChannelCatalogue.normalized(state.channelName).equals(ChannelCatalogue.normalized(name))){Bitmap nativeLogo=CHMAXIntegration.logo(context,state,false);if(nativeLogo!=null)return nativeLogo;}JSONObject j=new ChannelCatalogue(context).logo(name,id);
  try{Bitmap english=EnglishChannelLogos.fetch(context,j.optString("englishName",name),j.optString("country","US"),nativeId);if(english!=null){context.getSharedPreferences("smarthub",0).edit().putString("online_network:"+nativeId,j.optString("network")).putString("online_logo_public:"+nativeId,j.optString("channel")).apply();return english;}}catch(Exception unavailable){}if(!"matched".equals(j.optString("status")))return null;JSONArray images=j.optJSONArray("images");if(images==null)return null;
  for(int i=0;i<Math.min(images.length(),3);i++){JSONObject image=images.optJSONObject(i);if(image==null)continue;URI uri=new URI(image.optString("url"));if(!"https".equals(uri.getScheme())||uri.getHost()==null||uri.getUserInfo()!=null)continue;try{byte[] bytes=ArtworkCache.fetch(context,uri.toURL(),5*1024*1024);if(("SVG".equalsIgnoreCase(image.optString("format"))||uri.getPath().endsWith(".svg"))&&new String(bytes,0,Math.min(100,bytes.length),java.nio.charset.StandardCharsets.UTF_8).replace("\uFEFF","").trim().startsWith("<")){String xml=new String(bytes,java.nio.charset.StandardCharsets.UTF_8);if(xml.toUpperCase(java.util.Locale.ROOT).contains("<!DOCTYPE")||xml.toUpperCase(java.util.Locale.ROOT).contains("<!ENTITY"))continue;com.caverock.androidsvg.SVG svg=com.caverock.androidsvg.SVG.getFromString(xml);float ratio=svg.getDocumentAspectRatio();if(!Float.isFinite(ratio)||ratio<=0)ratio=1;int w=ratio>=1?1536:Math.max(1,Math.round(1536*ratio)),h=ratio>=1?Math.max(1,Math.round(1536/ratio)):1536;Bitmap bitmap=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);new Canvas(bitmap).drawPicture(svg.renderToPicture(w,h));remember(context,j,image,nativeId);return bitmap;}BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,bounds);if(bounds.outWidth<=0||bounds.outHeight<=0||bounds.outWidth>20000||bounds.outHeight>20000)continue;BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=1;while(bounds.outWidth/options.inSampleSize>1536||bounds.outHeight/options.inSampleSize>1536)options.inSampleSize*=2;Bitmap bitmap=BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);if(bitmap!=null){remember(context,j,image,nativeId);return bitmap;}}catch(Exception unavailable){/* try another verified logo format */}}
  return null;
 }
 static void remember(Context c,JSONObject data,JSONObject image,String nativeId){c.getSharedPreferences("smarthub",0).edit().putString("online_network:"+nativeId,data.optString("network")).putString("online_logo_public:"+nativeId,data.optString("channel")).putString("online_logo_url:"+nativeId,image.optString("url")).apply();}
 static byte[] read(HttpURLConnection c,int max)throws Exception{c.setConnectTimeout(6000);c.setReadTimeout(20000);c.setInstanceFollowRedirects(false);try{if(c.getResponseCode()!=200)throw new IOException("Logo source HTTP "+c.getResponseCode());try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] bytes=new byte[8192];int n;while((n=in.read(bytes))!=-1){if(out.size()+n>max)throw new IOException("Logo exceeds size limit");out.write(bytes,0,n);}return out.toByteArray();}}finally{c.disconnect();}}
}
